#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846
#define SAMPLE_RATE 44100
#define FREQUENCY 440
#define DURATION 1 // in seconds

int main() {
    int num_samples = SAMPLE_RATE * DURATION;
    double signal[num_samples];

    // Prepare the signal (a sine wave in this case)
    for (int i = 0; i < num_samples; i++) {
        double time = i / (double)SAMPLE_RATE;
        signal[i] = sin(2 * PI * FREQUENCY * time);
    }

    // Print the first few samples of the signal
    for (int i = 0; i < 10; i++) {
        printf("Sample %d: %f\n", i, signal[i]);
    }

    return 0;
}
